custom_css:
/* MoodTube theme: Pink Scrapbook. Pink paper, a handwritten tag, a taped polaroid and a magenta CD. */
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@500;600;700&family=Great+Vibes&family=Inter:wght@400;500;600;700&display=swap');

/* palette for every window */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal {
  --t-paper: #f7c6d6;
  --t-paper2: #fbd9e5;
  --t-card: #fff0f5;
  --t-mag: #d81b6a;
  --t-mag2: #b0124f;
  --t-ink: #2b1520;
  --t-dim: #8a4a65;
  --t-line: rgba(176, 18, 79, 0.28);
  --t-line2: rgba(176, 18, 79, 0.14);
  --mt-bg-primary: var(--t-paper);
  --mt-bg-secondary: var(--t-paper2);
  --mt-bg-input: var(--t-card);
  --mt-accent: var(--t-mag);
  --mt-accent-hover: var(--t-mag2);
  --mt-border: var(--t-line);
  --mt-text: var(--t-ink);
  --mt-text-dim: var(--t-dim);
  --mt-text-on-accent: #ffffff;
  --mt-text-strong: var(--t-ink);
  --mt-divider: var(--t-line2);
  --mt-overlay: rgba(70, 10, 40, 0.5);
  --mt-modal-shadow: 0 18px 40px rgba(80, 10, 40, 0.45);
  --mt-pl-spotify-tab: var(--t-ink);
  --mt-pl-spotify-tab-text: #ffffff;
}

.mt-progress {
  --mt-slider-track: rgba(176, 18, 79, 0.2);
  --mt-slider-track-height: 3px;
  --mt-slider-track-radius: 2px;
  --mt-slider-progress: #2b1520;
  --mt-slider-thumb-size: 11px;
  --mt-slider-thumb-bg: #2b1520;
  --mt-slider-thumb-bg-hover: #d81b6a;
  --mt-slider-thumb-border: 2px solid #ffffff;
  --mt-slider-thumb-radius: 50%;
  --mt-slider-thumb-shadow: none;
}
.mt-volume {
  --mt-slider-track: rgba(176, 18, 79, 0.2);
  --mt-slider-track-height: 3px;
  --mt-slider-track-radius: 2px;
  --mt-slider-progress: #d81b6a;
  --mt-slider-thumb-size: 9px;
  --mt-slider-thumb-bg: #d81b6a;
  --mt-slider-thumb-bg-hover: #2b1520;
  --mt-slider-thumb-border: none;
  --mt-slider-thumb-radius: 50%;
  --mt-slider-thumb-shadow: none;
}

/* the paper */
.mt-player {
  container-type: size;
  padding: 44px 16px 14px;
  background:
    radial-gradient(circle at 30% 12%, rgba(255, 255, 255, 0.4), transparent 55%),
    repeating-linear-gradient(115deg, rgba(255, 255, 255, 0.06) 0, rgba(255, 255, 255, 0.06) 2px, transparent 2px, transparent 5px),
    #f7c6d6;
  border: none;
  border-radius: 16px;
  color: var(--t-ink);
  font-family: 'Inter', sans-serif;
  box-shadow: 0 14px 28px rgba(80, 10, 40, 0.38);
  backdrop-filter: none;
}
.mt-player * { font-family: inherit; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }

#moodtube-mini-player, #moodtube-mini-player *, #mt-settings-modal, #mt-settings-modal *, .mt-fab, .mt-fab *, .mt-pl-modal, .mt-pl-modal *, #moodtube-dock, #moodtube-dock * {
  text-shadow: none;
}

/* two little hearts, no more */
.mt-slot-scene::before, .mt-slot-scene::after {
  content: '\2665';
  position: absolute;
  color: var(--t-mag);
  pointer-events: none;
}
.mt-slot-scene::before { right: 22px; top: 48px; font-size: 12px; rotate: 14deg; }
.mt-slot-scene::after { left: 9px; bottom: 16px; font-size: 9px; rotate: -18deg; }

/* header: a handwritten tag */
.mt-player-header { top: 12px; left: 12px; right: 96px; display: flex; align-items: center; }
.mt-player-header-title {
  position: relative;
  display: inline-block;
  padding: 5px 12px 4px 20px;
  background: #ffffff;
  clip-path: polygon(8px 0, 100% 0, 100% 100%, 8px 100%, 0 50%);
  filter: drop-shadow(0 2px 0 rgba(140, 10, 60, 0.25));
  rotate: -3deg;
  font-family: 'Great Vibes', cursive;
  font-size: 17px;
  font-weight: 400;
  line-height: 1.1;
  color: var(--t-mag);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}
.mt-player-header-title::before {
  content: '';
  position: absolute;
  left: 8px; top: 50%;
  width: 5px; height: 5px;
  margin-top: -2.5px;
  border-radius: 50%;
  background: #f7c6d6;
  box-shadow: inset 0 0 0 1px #e7a1b8;
}
.mt-player-status { display: none; }

.mt-window-btn {
  top: 14px;
  width: 20px;
  height: 20px;
  font-size: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  line-height: 1;
  box-sizing: border-box;
  border-radius: 50%;
  background: #ffffff;
  color: var(--t-mag2);
  cursor: pointer;
  transition: background-color 0.15s, color 0.15s;
}
.mt-window-btn:hover { background: var(--t-mag); color: #ffffff; }

.mt-player-body { gap: 8px; justify-content: flex-start; }

/* cover: a taped polaroid and a CD behind it */
.mt-cover {
  width: 100%;
  max-width: 230px;
  height: 148px;
  margin: 0 auto;
  border-radius: 0;
  border: none;
  background: transparent;
  box-shadow: none;
  overflow: visible;
  flex-shrink: 0;
  display: block;
}
.mt-slot-cover-bg {
  inset: 14px 8px auto auto;
  width: 112px;
  height: 112px;
  border-radius: 50%;
  background:
    radial-gradient(circle, #f7c6d6 0 8px, #f3a7c4 8.5px 14px, transparent 14.5px),
    repeating-radial-gradient(circle, rgba(255, 255, 255, 0.12) 0 1px, transparent 1px 4px),
    #d81b6a;
  box-shadow: 0 3px 0 rgba(120, 10, 50, 0.3);
  animation: mt-sb-spin 10s linear infinite;
  animation-play-state: paused;
}
.mt-player.mt-is-playing .mt-slot-cover-bg { animation-play-state: running; }
@keyframes mt-sb-spin { to { rotate: 360deg; } }

img.mt-cover-img {
  position: absolute;
  left: 8px;
  top: 6px;
  width: 98px;
  height: 98px;
  box-sizing: content-box;
  padding: 7px 7px 24px;
  background: #ffffff;
  border-radius: 1px;
  object-fit: cover;
  rotate: -5deg;
  box-shadow: 0 3px 0 rgba(120, 10, 50, 0.25);
  z-index: 1;
}
.mt-slot-cover { z-index: 2; border-radius: 0; background: transparent; }
.mt-slot-cover::before {
  content: '';
  position: absolute;
  left: 44px; top: -3px;
  width: 46px; height: 14px;
  rotate: 4deg;
  background: repeating-linear-gradient(90deg, rgba(255, 170, 200, 0.78) 0, rgba(255, 170, 200, 0.78) 4px, rgba(255, 215, 228, 0.78) 4px, rgba(255, 215, 228, 0.78) 8px);
}
.mt-slot-cover::after {
  content: 'on repeat';
  position: absolute;
  left: 9px; top: 113px;
  width: 112px;
  text-align: center;
  rotate: -5deg;
  font-family: 'Great Vibes', cursive;
  font-size: 14px;
  line-height: 1;
  color: var(--t-mag);
}
.mt-cover-hole { display: none; }

/* track info */
.mt-track-info { width: 100%; box-sizing: border-box; padding: 0 28px 0 2px; text-align: left; align-items: flex-start; }
#moodtube-mini-player .mt-track-title {
  font-family: 'Oswald', 'Inter', sans-serif;
  font-size: 21px;
  font-weight: 600;
  letter-spacing: 0.02em;
  line-height: 1.1;
  text-transform: uppercase;
  color: var(--t-mag);
}
.mt-track-subtitle {
  margin-top: 2px;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--t-mag2);
}
.mt-btn-favorite {
  top: 2px;
  right: 2px;
  width: 24px;
  height: 24px;
  padding: 0;
  background: none;
  border: none;
  font-size: 16px;
  color: rgba(176, 18, 79, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.mt-btn-favorite:hover { color: var(--t-mag); }
.mt-btn-favorite.mt-is-active { color: var(--t-mag); }

.mt-progress { gap: 6px; margin-top: 0; }
.mt-time-current, .mt-time-total { font-size: 9px; font-weight: 500; color: #7a3a55; }

/* buttons: width + height + font-size on every one */
.mt-controls { width: 100%; gap: 4px; justify-content: space-between; padding: 0 4px; box-sizing: border-box; }
.mt-controls > .mt-btn {
  width: 32px;
  height: 32px;
  font-size: 14px;
  padding: 0;
  line-height: 1;
  box-sizing: border-box;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: transparent;
  border: none;
  color: var(--t-ink);
  cursor: pointer;
  transition: color 0.15s, background-color 0.15s;
}
.mt-controls > .mt-btn:hover { color: var(--t-mag); background: rgba(255, 255, 255, 0.5); }
.mt-controls > .mt-btn.mt-btn-play {
  width: 44px;
  height: 44px;
  font-size: 16px;
  background: var(--t-ink);
  color: #ffffff;
}
.mt-controls > .mt-btn.mt-btn-play:hover { background: var(--t-mag); color: #ffffff; }
.mt-btn-play.fa-play { padding-left: 2px; }
.mt-controls > .mt-btn.mt-btn-ai.mt-is-busy { color: var(--t-mag); animation: mt-sb-pulse 1s ease-in-out infinite alternate; }
@keyframes mt-sb-pulse { to { scale: 1.12; } }

.mt-volume { gap: 6px; width: 92%; }
.mt-volume-low, .mt-volume-high { font-size: 11px; color: var(--t-mag2); }

/* panels */
.mt-panel {
  background:
    repeating-linear-gradient(115deg, rgba(255, 255, 255, 0.06) 0, rgba(255, 255, 255, 0.06) 2px, transparent 2px, transparent 5px),
    #f7c6d6;
  color: var(--t-ink);
  padding-top: 46px;
  border-radius: inherit;
}
.mt-panel-search { --mt-bg-primary: #f7c6d6; }
.mt-panel-header { border-bottom: 1.5px dashed var(--t-mag); padding-bottom: 6px; }
.mt-panel-title { font-family: 'Oswald', sans-serif; font-size: 12px; font-weight: 600; letter-spacing: 0.02em; text-transform: uppercase; color: var(--t-mag); }
.mt-panel-close { color: var(--t-mag2); }
.mt-panel-close:hover { color: var(--t-mag); }

.mt-queue-item { padding: 6px 8px; margin-bottom: 4px; border-radius: 10px; background: rgba(255, 255, 255, 0.55); border: 1px solid transparent; }
.mt-queue-item:hover { background: #ffffff; }
.mt-queue-item.mt-is-current { background: #ffffff; border-color: var(--t-mag); }
.mt-queue-thumb { border-radius: 3px; border: 2px solid #ffffff; }
.mt-queue-title { color: var(--t-ink); font-weight: 600; font-size: 12px; }
.mt-queue-now { color: var(--t-mag); }
.mt-queue-add { color: var(--t-mag2); }
.mt-queue-add:hover { color: var(--t-mag); }
.mt-queue-dislike { background-color: var(--t-dim); }
.mt-queue-dislike:hover { background-color: var(--t-mag); }
.mt-queue-empty { color: var(--t-dim); }

.mt-pl-tabs { border-bottom: 1.5px dashed var(--t-mag); gap: 6px; }
.mt-pl-tab { font-size: 11px; font-weight: 600; color: var(--t-mag2); background: rgba(255, 255, 255, 0.55); border: 1px solid transparent; border-radius: 999px; }
.mt-pl-tab.mt-is-active { background: var(--t-ink); color: #ffffff; }
.mt-playlist-item { border-radius: 10px; }
.mt-playlist-item:hover { background: rgba(255, 255, 255, 0.7); }
.mt-playlist-title { color: var(--t-ink); font-weight: 600; }
.mt-pl-count { color: var(--t-dim); }
.mt-pl-cover { border-radius: 3px; border: 2px solid #ffffff; }
.mt-pl-tool { background: rgba(255, 255, 255, 0.7); color: var(--t-ink); border: none; border-radius: 50%; }
.mt-pl-tool.mt-pl-play, .mt-pl-tool:hover { background: var(--t-ink); color: #ffffff; }

#moodtube-search-input { background: #ffffff; color: var(--t-ink); border: 1px solid var(--t-line); border-radius: 999px; }
#moodtube-search-go { background: var(--t-ink); color: #ffffff; border: none; border-radius: 999px; }
#moodtube-search-go:hover { background: var(--t-mag); }

/* floating button, also when docked next to the input */
.mt-fab, .mt-fab.mt-fab-docked {
  background: #ffffff;
  border: 2px solid var(--t-mag);
  border-radius: 50%;
  color: var(--t-mag);
  box-shadow: 0 4px 12px rgba(80, 10, 40, 0.35);
}
.mt-fab:hover, .mt-fab.mt-fab-docked:hover { background: var(--t-mag); color: #ffffff; }

/* add-to-playlist window */
.mt-pl-modal-box {
  background: #f7c6d6;
  color: var(--t-ink);
  border: none;
  border-radius: 16px;
  box-shadow: 0 16px 40px rgba(80, 10, 40, 0.45);
}
.mt-pl-modal-track { color: var(--t-mag); font-weight: 700; }
.mt-pl-option { color: var(--t-ink); border: 1px solid transparent; border-radius: 10px; background: rgba(255, 255, 255, 0.6); }
.mt-pl-option:hover { background: #ffffff; border-color: var(--t-mag); }
.mt-pl-option.mt-is-added { background: var(--t-ink); color: #ffffff; border-color: var(--t-ink); }

/* settings */
#mt-settings-modal .mt-flex-container {
  background: #f7c6d6;
  color: var(--t-ink);
  border: none;
  border-radius: 18px;
  box-shadow: 0 20px 48px rgba(80, 10, 40, 0.5);
  font-family: 'Inter', sans-serif;
}
#mt-settings-modal .mt-header h3 { font-family: 'Oswald', sans-serif; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; color: var(--t-mag); }
#mt-settings-modal .mt-close { color: var(--t-mag2); }
#mt-settings-modal .mt-close:hover { color: var(--t-mag); }
#mt-settings-modal .mt-subpanel { background: rgba(255, 255, 255, 0.6); border: 1px solid var(--t-line2); border-radius: 12px; }
#mt-settings-modal .mt-btn-test {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: var(--t-ink);
  color: #ffffff;
  border: none;
  border-radius: 999px;
  padding: 8px 14px;
  font-weight: 600;
  cursor: pointer;
}
#mt-settings-modal .mt-btn-test:hover { background: var(--t-mag); }
.mt-tag, .mt-genre-tag, .mt-mood-tag, .mt-scenario-tag {
  background: rgba(255, 255, 255, 0.65);
  border: 1px solid transparent;
  color: var(--t-mag2);
  border-radius: 999px;
  padding: 4px 10px;
}
.mt-tag:hover, .mt-genre-tag:hover, .mt-mood-tag:hover, .mt-scenario-tag:hover { background: #ffffff; border-color: var(--t-mag); }
.mt-tag.active, .mt-genre-tag.active, .mt-mood-tag.active, .mt-scenario-tag.active { background: var(--t-mag); color: #ffffff; font-weight: 700; }

.mt-player ::-webkit-scrollbar, #mt-settings-modal ::-webkit-scrollbar, .mt-pl-modal-box ::-webkit-scrollbar { width: 5px; height: 5px; }
.mt-player ::-webkit-scrollbar-track, #mt-settings-modal ::-webkit-scrollbar-track, .mt-pl-modal-box ::-webkit-scrollbar-track { background: rgba(255, 255, 255, 0.35); }
.mt-player ::-webkit-scrollbar-thumb, #mt-settings-modal ::-webkit-scrollbar-thumb, .mt-pl-modal-box ::-webkit-scrollbar-thumb { background: var(--t-mag); border-radius: 99px; }

/* sizes and modes */
@container (max-width: 640px) { .mt-player.moodtube-row-layout .mt-volume { display: none; } }

/* wide strip: the CD goes, the polaroid becomes a small photo */
.mt-player.moodtube-row-layout#moodtube-mini-player { padding: 38px 16px 12px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-player-body { flex-direction: row; align-items: center; justify-content: space-between; gap: 12px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-cover { width: 54px; height: 62px; max-width: none; margin: 0; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-slot-cover-bg,
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-slot-cover::after,
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-slot-cover::before { display: none; }
.mt-player.moodtube-row-layout#moodtube-mini-player img.mt-cover-img { left: 0; top: 0; width: 42px; height: 42px; padding: 4px 4px 12px; rotate: -4deg; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-track-info { min-width: 110px; max-width: 160px; flex: 0 1 150px; padding: 0 22px 0 0; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-track-title { font-size: 16px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-progress { flex: 1 1 90px; min-width: 90px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls { width: auto; gap: 2px; flex-shrink: 0; padding: 0; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls > .mt-btn { width: 28px; height: 28px; font-size: 12px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-controls > .mt-btn.mt-btn-play { width: 36px; height: 36px; font-size: 13px; }
.mt-player.moodtube-row-layout#moodtube-mini-player .mt-volume { width: 76px; flex-shrink: 0; }

/* short window: the CD hides */
@container (max-height: 250px) {
  .mt-player:not(.moodtube-row-layout) .mt-cover { height: 118px; max-width: 170px; }
  .mt-player:not(.moodtube-row-layout) .mt-slot-cover-bg { width: 84px; height: 84px; top: 10px; }
  .mt-player:not(.moodtube-row-layout) img.mt-cover-img { width: 72px; height: 72px; padding: 6px 6px 18px; }
  .mt-player:not(.moodtube-row-layout) .mt-slot-cover::after { top: 78px; width: 84px; font-size: 12px; }
  #moodtube-mini-player:not(.moodtube-row-layout) .mt-track-title { font-size: 17px; }
}
/* small square (about 200x200) */
@container (max-width: 190px) {
  .mt-player .mt-controls > .mt-btn { width: 28px; height: 28px; font-size: 12px; }
  .mt-player .mt-controls > .mt-btn.mt-btn-play { width: 38px; height: 38px; font-size: 14px; }
  #moodtube-mini-player .mt-track-title { font-size: 17px; }
}

/* under the tavern header: paper without a rounded card */
#moodtube-mini-player.mt-player-docked { background: transparent; }
.mt-player-docked .mt-panel { border-radius: 0; }

/* dock strip: a taped photo and magenta title */
#moodtube-dock { background: repeating-linear-gradient(115deg, rgba(255, 255, 255, 0.06) 0, rgba(255, 255, 255, 0.06) 2px, transparent 2px, transparent 5px), #f7c6d6; border-bottom: 1px solid #e79ab5; }
#moodtube-dock .mt-dock-title { font-family: 'Oswald', sans-serif; font-size: 14px; font-weight: 600; letter-spacing: 0.03em; text-transform: uppercase; color: #d81b6a; }
#moodtube-dock .mt-dock-subtitle { font-size: 9px; font-weight: 600; letter-spacing: 0.14em; text-transform: uppercase; color: #b0124f; }
#moodtube-dock .mt-dock-inner .mt-dock-cover { width: 34px; height: 34px; border: 3px solid #ffffff; border-bottom-width: 7px; border-radius: 1px; rotate: -5deg; background: #ffffff; box-shadow: 0 2px 0 rgba(120, 10, 50, 0.25); box-sizing: content-box; }

/* ===== Dock bar (strip under the tavern header) [auto] ===== */
#moodtube-dock {
  font-family: 'Inter', sans-serif;
  --mt-dock-cover-radius: 2px;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border-width: 1.5px; }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box; line-height: 1; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; border-radius: 50%;
  font-size: 12px; color: var(--mt-text);
  background: color-mix(in srgb, var(--mt-accent) 12%, transparent);
  transform: none; transition: background-color 0.2s;
}
#moodtube-dock .mt-dock-btn:hover { transform: none; color: var(--mt-text); background: color-mix(in srgb, var(--mt-accent) 28%, transparent); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  background: var(--mt-accent); color: var(--mt-text-on-accent, #ffffff);
}
#moodtube-dock .mt-dock-play:hover { background: var(--mt-accent-hover, var(--mt-accent)); color: var(--mt-text-on-accent, #ffffff); }
#moodtube-dock .mt-dock-play.fa-play { padding-left: 2px; }
#moodtube-dock .mt-dock-fav, #moodtube-dock .mt-dock-ai, #moodtube-dock .mt-dock-queue { color: var(--mt-text); }
#moodtube-dock .mt-dock-fav.mt-is-active, #moodtube-dock .mt-dock-ai.mt-is-busy { color: var(--mt-accent); }
#moodtube-dock .mt-dock-expand, #moodtube-dock .mt-dock-close { color: var(--mt-text-dim, var(--mt-text)); }
#moodtube-dock .mt-dock-queue.mt-is-open, #moodtube-dock .mt-dock-expand.mt-is-open {
  color: var(--mt-text); text-shadow: none; background: color-mix(in srgb, var(--mt-accent) 30%, transparent);
}
#moodtube-dock .mt-dock-progress { height: 3px; }
@media (max-width: 420px) {
  #moodtube-dock .mt-dock-inner { gap: 6px; padding-left: 8px; padding-right: 8px; }
  #moodtube-dock .mt-dock-controls { gap: 3px; }
  #moodtube-dock .mt-dock-btn { width: 24px; height: 24px; font-size: 11px; }
  #moodtube-dock .mt-dock-play { width: 28px; height: 28px; font-size: 12px; }
}
/* ===== /Dock bar ===== */
